#include <set>

using namespace std;

class ExamRoom {
    int N;
    set<int> seats;

public:
    ExamRoom(int n) : N(n) {}

    int seat() {
        if (seats.empty()) {
            seats.insert(0);
            return 0;
        }

        int prev = -1, maxDist = 0, seatToTake = 0;
        for (int seat : seats) {
            if (prev == -1) {
                if (seat > 0) {
                    maxDist = seat;
                    seatToTake = 0;
                }
            } else {
                int dist = (seat - prev) / 2;
                if (dist > maxDist) {
                    maxDist = dist;
                    seatToTake = prev + dist;
                }
            }
            prev = seat;
        }

        if (N - 1 - *seats.rbegin() > maxDist) {
            seatToTake = N - 1;
        }

        seats.insert(seatToTake);
        return seatToTake;
    }

    void leave(int p) {
        seats.erase(p);
    }
};
